        return None

    elif name == 'finance/attach':
        if not label.subset.issubset({'PCI'}):
            raise PolicyViolation('finance/attach only allowed to read/write PCI')
        target = 'slot:request'
        if target in policy_dict and not label.subset.isdisjoint(policy_dict[target]):
            raise PolicyViolation('Target slot:request forbids labels in {}'.format(label.subset))
        return None

    elif name == 'travel/submit':
        source = args.get('source')
        target = args.get('target')

        if target == 'agency':
            if not label.subset.isdisjoint({'PCI'}):
                raise PolicyViolation('Cannot send PCI to slot:agency')
            return None

        elif target == 'finance':
            return None

        elif target == 'board':
            if not label.subset.isdisjoint({'PII', 'PCI'}):
                raise PolicyViolation('Cannot send PII or PCI to slot:board')
            return None

        else:
            return None

    else:
        raise PolicyViolation('Unknown action {}'.format(name))
